sys_script_client.script:
function onSubmit() {
    var caseId = g_form.getUniqueValue(); // assume this script is on task form
    var ga = new GlideAjax('MSSTrusteesCallUtils');
    ga.addParam('sysparm_name', 'gettaskassigned');
    ga.addParam('sysparm_case_id', caseId);
    ga.getXMLAnswer(function(response) {
        var assignedTotask = response;
        if (assignedTotask == g_user.userID) {
            g_form.setValue('assigned_to', '');
            g_form.clearMessages();
            g_form.addErrorMessage("Task assignee cannot be the same as Case assignee");
            return false;
        }
    });
    // Allow submit to continue (return true by default)
    return true;
}
